/*
 * Script JScript para Enterprise Architect (Sparx Systems).
 * Crea los paquetes, elementos, relaciones y diagramas del proyecto
 * "Sistema Web - Carrera de Administracion de Empresas".
 *
 * Uso: seleccione un paquete vacio en el Explorador del proyecto, abra
 * Especificar > Herramientas > Scripting (o Ctrl+Alt+... "Scripting"),
 * cree un script JScript nuevo en un grupo "Normal", pegue este contenido y ejecutelo.
 * El script trabaja dentro del paquete seleccionado.
 */

var P = {};   // paquetes por clave
var E = {};   // ElementID por clave
var C = {};   // ConnectorID por clave
var D = {};   // diagramas por clave

function log(t) { Session.Output(t); }

function paquete(clave, padreClave, nombre) {
    var padre = padreClave ? P[padreClave] : Repository.GetTreeSelectedPackage();
    var p = padre.Packages.AddNew(nombre, "");
    p.Update();
    padre.Packages.Refresh();
    P[clave] = p;
    if (p.Element != null) { E["pkgel:" + clave] = p.Element.ElementID; }
    return p;
}

function elemento(clave, paqClave, nombre, tipo, estereotipo, abstracto) {
    var pk = P[paqClave];
    var e = pk.Elements.AddNew(nombre, tipo);
    if (estereotipo) { e.Stereotype = estereotipo; }
    if (abstracto) { e.Abstract = "1"; }
    e.Update();
    pk.Elements.Refresh();
    E[clave] = e.ElementID;
    return e;
}

function atributo(clave, nombre, tipo, vis, est, estatico) {
    var e = Repository.GetElementByID(E[clave]);
    var a = e.Attributes.AddNew(nombre, tipo);
    a.Visibility = vis;
    if (est) { a.Stereotype = est; }
    if (estatico) { a.IsStatic = true; }
    a.Update();
    e.Attributes.Refresh();
}

function metodo(clave, nombre, ret, vis, params, estatico, abstracto) {
    var e = Repository.GetElementByID(E[clave]);
    var m = e.Methods.AddNew(nombre, ret);
    m.Visibility = vis;
    if (estatico) { m.IsStatic = true; }
    if (abstracto) { m.Abstract = true; }
    m.Update();
    for (var i = 0; i < params.length; i++) {
        var p = m.Parameters.AddNew(params[i][0], params[i][1]);
        p.Kind = "in";
        p.Update();
    }
    m.Parameters.Refresh();
    e.Methods.Refresh();
}

function conector(clave, origen, destino, tipo, nombre, est, direccion, multO, multD) {
    var s = Repository.GetElementByID(E[origen]);
    var c = s.Connectors.AddNew(nombre, tipo);
    c.SupplierID = E[destino];
    if (est) { c.Stereotype = est; }
    if (direccion) { c.Direction = direccion; }
    c.Update();
    if (multO) { c.ClientEnd.Cardinality = multO; c.ClientEnd.Update(); }
    if (multD) { c.SupplierEnd.Cardinality = multD; c.SupplierEnd.Update(); }
    s.Connectors.Refresh();
    C[clave] = c.ConnectorID;
    return c;
}

function diagrama(clave, paqClave, nombre, tipo) {
    var pk = P[paqClave];
    var d = pk.Diagrams.AddNew(nombre, tipo);
    d.Update();
    pk.Diagrams.Refresh();
    D[clave] = d;
    return d;
}

function poner(dClave, elClave, l, t, r, b, seq) {
    var d = D[dClave];
    var o = d.DiagramObjects.AddNew("l=" + l + ";r=" + r + ";t=" + t + ";b=" + b + ";", "");
    o.ElementID = E[elClave];
    o.Sequence = seq;
    o.Update();
}

function ocultar(dClave, conClave) {
    var d = D[dClave];
    try {
        var dl = d.DiagramLinks.AddNew("", "");
        dl.ConnectorID = C[conClave];
        dl.IsHidden = true;
        dl.Update();
    } catch (err) { log("No se pudo ocultar un conector: " + err.message); }
}

function mensaje(dClave, origen, destino, nombre, n, retorno) {
    var d = D[dClave];
    var s = Repository.GetElementByID(E[origen]);
    var c = s.Connectors.AddNew(nombre, "Sequence");
    c.SupplierID = E[destino];
    c.DiagramID = d.DiagramID;
    c.SequenceNo = n;
    c.Update();
    s.Connectors.Refresh();
    if (retorno) {
        try { Repository.Execute("UPDATE t_connector SET PDATA4='1' WHERE Connector_ID=" + c.ConnectorID); } catch (err) { }
    }
}

function terminar(dClave) {
    var d = D[dClave];
    d.DiagramObjects.Refresh();
    d.Update();
}

